package com.nattechnologies.trastcms.plugins.pay.cleanpay;
import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/commerce/gateways/cleanpay") public class CleanPayAdminController{private final CleanPayClient client;public CleanPayAdminController(CleanPayClient c){client=c;}@GetMapping public Map<String,Object> get(){CleanPaySettings s=client.settings();Map<String,Object> m=new LinkedHashMap<>();m.put("enabled",s.isEnabled());m.put("apiUrl",s.getApiUrl());m.put("statusUrl",s.getStatusUrl());m.put("merchantId",s.getMerchantId());m.put("terminalId",s.getTerminalId());m.put("authHeader",s.getAuthHeader());m.put("authScheme",s.getAuthScheme());m.put("tokenConfigured",s.getTokenEncrypted()!=null&&!s.getTokenEncrypted().isBlank());m.put("threeDsEnabled",s.isThreeDsEnabled());m.put("returnUrl",s.getReturnUrl());m.put("cancelUrl",s.getCancelUrl());m.put("timeoutSeconds",s.getTimeoutSeconds());m.put("additionalJson",s.getAdditionalJson());return m;}@PutMapping public Map<String,Object> save(@RequestBody Request r){CleanPaySettings s=new CleanPaySettings();s.setEnabled(r.enabled);s.setApiUrl(r.apiUrl);s.setStatusUrl(r.statusUrl);s.setMerchantId(r.merchantId);s.setTerminalId(r.terminalId);s.setAuthHeader(r.authHeader);s.setAuthScheme(r.authScheme);s.setThreeDsEnabled(r.threeDsEnabled);s.setReturnUrl(r.returnUrl);s.setCancelUrl(r.cancelUrl);s.setTimeoutSeconds(r.timeoutSeconds);s.setAdditionalJson(r.additionalJson);client.save(s,r.token);return get();}@PostMapping("/test") public CleanPayClient.GatewayResponse test(@RequestBody Map<String,Object> payload){return client.charge(payload);}public static class Request{public boolean enabled;public String apiUrl,statusUrl,merchantId,terminalId,authHeader,authScheme,token,returnUrl,cancelUrl,additionalJson;public boolean threeDsEnabled=true;public int timeoutSeconds=30;}}
